  S["Któryś wymiar nie jest liczbą. Wpisz same cyfry z separatorem dziesiętnym, na przykład {przyklad}."]="One of the dimensions is not a number. Enter digits with a decimal separator only, for example {przyklad}.";
  S["długość"]="length";
